package com.agicore.dialogue; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; import com.agicore.domain.Contracts.Route;
class DialogueRouterTest { DialogueRouter r=new DialogueRouter(); @Test void priority(){assertEquals(Route.RAG,r.route("rag","",new DialogueRouter.ListFlag(true,true,true))); assertEquals(Route.GRAPH,r.route(null,"",new DialogueRouter.ListFlag(false,true,true))); assertEquals(Route.RAG,r.route(null,"",new DialogueRouter.ListFlag(false,false,true))); assertEquals(Route.CHAT,r.route(null,"",new DialogueRouter.ListFlag(false,false,false)));} }
